func atoi(s string) int {
	v, _ := strconv.Atoi(strings.TrimSpace(s))
	return v
}

func readAllInt(s string) []int {
	f := strings.Fields(s)
	res := make([]int, len(f))
	for i, w := range f {
		res[i] = atoi(w)
	}
	return res
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	lines := strings.Split(strings.ReplaceAll(string(data), "\r", ""), "\n")
	line := func(i int) string {
		if i < len(lines) {
			return lines[i]
		}
		return ""
	}
	nums := readAllInt(line(0))
	target := atoi(strings.TrimSpace(line(1)))
	result := solve(nums, target)
	fmt.Println(result)
}

